  "claims": [
    {
      "claim": "Direct human absolute oral bioavailability values for steroid-like molecules in the pool are all below 20%: beta-sitosterol 0.41% (C01), testosterone undecanoate 6.83% (C04), danazol 11-19% fasted (C08, C05, C17, C33), and abiraterone acetate below 10% fasted (C14, C22, C31).",
      "card_ids": ["C01","C04","C08","C05","C17","C33","C14","C22","C31"]
    },
    {
      "claim": "Phenolic steroid scaffolds are consistently reported as low or poor: fulvestrant (C09, C10, C11, C12, C15, C20, C24, C27, C29, C30), thienorphine very low (C23), nestorone low (C06), and dimethandrolone undecanoate poor and inconsistent (C07).",
      "card_ids": ["C09","C10","C11","C12","C15","C20","C24","C27","C29","C30","C23","C06","C07"]
    },
    {
      "claim": "L2 records add quantitative low-F values that reinforce the L1 outcomes: oleanolic acid absolute 0.7% in rats (C84, C87), ursolic acid absolute 1.18% in rats (C83), danazol 11-17% fasted (C40, C60, C74), and abiraterone below 10% fasted (C65, C88, C96).",
      "card_ids": ["C84","C87","C83","C40","C60","C74","C65","C88","C96"]
    },
    {
      "claim": "Apparent contradictions are relative or non-absolute measures that do not establish F at or above 20%: thienorphine better than buprenorphine (C36, C43) uses a low-F comparator, abiraterone relative F of 115.92% (C66) is test-versus-reference oral product, oleanolic acid apparent F of 100% (C69) is an apparent rat value at high dose, and stigmasterol 43.83% (C58) is a different molecule.",
      "card_ids": ["C36","C43","C66","C69","C58"]
    },
    {
      "claim": "The query is a neutral rigid steroid phenol-diol with no basic site, aligning with the low-bioavailability phenolic steroid contexts in the pool; the physicochemical high prior is explicitly low-confidence and is not endpoint proof.",
      "card_ids": ["C09","C23","C14","C01"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C40","C60","C65","C74","C83","C84","C87","C88","C96","C36","C43","C66","C69","C81","C58"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule itself.",
    "No query-specific IV-oral comparison, dose, formulation, or prandial-state data.",
    "Transfer from steroid analogs is indirect; structural differences such as the extra ring and diol placement are not quantitatively matched.",
    "No direct solubility, permeability, or first-pass metabolism measurement for the query.",
    "Ursolic acid L1 (C18) reports detectable systemic exposure but no quantitative F value, so it does not establish F at or above 20%."
  ],
  "decision_summary": "L2 records reinforce the L1 picture. Steroid-like phenolic molecules consistently show low absolute oral bioavailability, with direct human values of 0.4-19%. Apparent contradictions are relative comparisons to low-F comparators or non-absolute measures. The query's neutral rigid phenol-diol steroid structure aligns with these low-F contexts, so F >= 20% is not better supported."
}

